"""Generate the original-source study note from saved results."""
import json,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def main():
    out=ROOT/'reports/original_512';s=json.loads((out/'summary.json').read_text());manifest=json.loads((out/'manifest.json').read_text());rows=list(csv.DictReader((out/'results.csv').open()))
    p=s['primary'];fine=s['contrasts']['mobile_512_finetuned_minus_mobile_512_probe']['auroc'];sel=s['selection']['mobile_512_finetuned']
    large=None
    if (out/'large_encoder/summary.json').exists():
        large=json.loads((out/'large_encoder/summary.json').read_text());rows.append(dict(arm='resnet50_224_probe',**large['metrics']))
    lines=['# Originalbilder, 512px und nachtrainierter Bildencoder','','Durchgeführt am 10. November 2026. Neuer Ausgangsvergleich mit Original-Thoraxaufnahmen aus der offiziellen Mendeley-Quelle, Auflösung 224/512, partiellem Encodertraining und einer größeren Architektur. Alle vorab festgelegten Arme werden berichtet; eine Verbesserung wird nicht vorausgesetzt.','','## Wichtigste Ergebnisse','',f"- Primär: MobileNet 512 minus 224, Test-AUROC **{p['point']:+.4f}**, gepaarter 95%-Gruppenbootstrap **[{p['ci'][0]:+.4f}; {p['ci'][1]:+.4f}]**.",f"- Nachtrainiert minus eingefroren bei 512: AUROC **{fine['point']:+.4f} [{fine['ci'][0]:+.4f}; {fine['ci'][1]:+.4f}]**. Sekundärer Vergleich.",f"- Gewählte Epoche: **{sel['selected_epoch']} von 0–3**, ausschließlich nach Modellwahl-NLL. Epoche 0 ist der unveränderte Ausgangskopf.",'','| Modell | AUROC | Accuracy | NLL | Fehler bei 80 % Abdeckung | Annahme bei fester Schwelle | Fehler unter angenommenen Fällen |','|---|---:|---:|---:|---:|---:|---:|']
    for r in rows:lines.append(f"| {r['arm']} | {float(r['auroc']):.4f} | {float(r['accuracy']):.1%} | {float(r['nll']):.4f} | {float(r['risk_at_80']):.1%} | {float(r['coverage']):.1%} | {float(r['retained_error']):.1%} |")
    lines+=['','![Modellvergleich und Trainingsverlauf](model_comparison.png)','','AUROC misst die Rangordnung über mögliche Schwellen; Accuracy verwendet Wahrscheinlichkeit 0,5. Beide ersetzen keine klinische Validierung. Selektive Fehler werden gemeinsam mit der jeweiligen Annahmemenge ausgewertet. Ein Modell mit niedrigerem Fehler bei stark reduzierter Annahme ist nicht automatisch besser.','','## Bildquelle und tatsächliche Auflösung','','Quelle: Kermany, Zhang & Goldbaum (2018), [Labeled OCT and Chest X-Ray Images for Classification, Version 2](https://data.mendeley.com/datasets/rscbjbr9sj/2), DOI 10.17632/rscbjbr9sj.2, CC BY 4.0. Ausschließlich `ChestXRay2017.zip` (1.235.512.464 Bytes), SHA-256 `13efc055629733dbab07877f8b3c9f81097840dbcdaa326a8542322c2281ce36`. Lizenz und Hash wurden an der offiziellen Quelle geprüft; keine Übernahme der unklaren RSNA-Spiegellizenz.','','Die Bilder stammen aus Original-JPEGs, nicht aus hochskaliertem MedMNIST. Das gesamte Bild wird mit Lanczos auf eine lange Kante von 224 oder 512 gebracht und mit schwarzen Rändern zum Quadrat ergänzt. Das Seitenverhältnis bleibt erhalten. Beide Arme erhalten dieselben Fälle. Bei 512 ändern sich räumliche Information und Encoder-Eingabegeometrie gemeinsam; der Vergleich isoliert nicht ausschließlich Bildinformation. Auch 512 ist oft weiterhin eine Verkleinerung.','','![Gleiche Originalaufnahme bei zwei Auflösungen](resolution_example.png)','','| Teilmenge | Bilder | Positive | Dateinamen-Gruppen | Lange Kante ursprünglich <512 | Kurze Kante ursprünglich <512 |','|---|---:|---:|---:|---:|---:|']
    for k,v in manifest['counts'].items():lines.append(f"| {k} | {v['n']} | {v['positive']} | {v['groups']} | {v['long_edge_below512']} | {v['short_edge_below512']} |")
    lines+=['','Alle 618 Testbilder haben eine ursprüngliche lange Kante von mindestens 728 Pixeln. 19 haben eine kurze Kante unter 512; der längere Bildrand wird trotzdem verkleinert und der freie Raum gepolstert. 55 Bilder außerhalb des Tests haben selbst an der langen Kante weniger als 512 Pixel und werden entsprechend gekennzeichnet.','','## Trennung und Herkunftsaudit','','Von 5.856 Bildern wurden 32 exakte dekodierte Grauwert-Duplikate entfernt (Testpriorität). Anschließend wurden 453 Trainingsbilder ausgeschlossen, deren aus dem Dateinamen abgeleitete Kennung auch im Test vorkommt. Alle 453 betreffen PNEUMONIA-Dateinamen. Das sind potenzielle Patientenüberschneidungen, keine nachträglich bestätigten medizinischen Identitäten. NORMAL/NORMAL2-Kennungen und person-Nummern werden nach ihrer Namenskonvention gruppiert; weitere Identitätsverknüpfungen können unbekannt bleiben.','','Der offizielle Testbestand bleibt ansonsten erhalten. Die übrigen Trainingsgruppen werden mit einem festgelegten stratified group split in Training, Modellwahl und Kalibrierung aufgeteilt. Kein Trainings-/Modellwahl-/Kalibrierungs-/Testpaar teilt eine erfasste Kennung oder identische Pixel. [Vollständiges Manifest samt Ausschlüssen](manifest.json).','','Dies ist dieselbe Quellfamilie wie MedMNIST, kein neuer externer klinischer Test. Die neue Bereinigung, Vorverarbeitung und Aufteilung ändern den Vergleichsmaßstab: frühere 224px-/28px-Zahlen dürfen nicht als direkt gepaarte Referenz verwendet werden.','','## Training und Kapazität','','ImageNet-vortrainiertes MobileNetV3-Small liefert einen mobilen Ausgangspunkt. Ein train-only StandardScaler und eine logistische Klassifikationsschicht werden für jeden eingefrorenen Arm angepasst; C ∈ {0,01; 0,1; 1; 10} wird nur nach Modellwahl-NLL gewählt. Größere Referenz: ResNet-18 bei 224px. Das ist ein Architektur-/Repräsentationsvergleich, kein isolierter Parameterzahl-Effekt.','','| Arm | Parameter inkl. neuem Kopf | Merkmalsdimension | Eingabe |','|---|---:|---:|---:|']
    for a,v in s['models'].items():lines.append(f"| {a} | {v['parameters']:,} | {v['feature_dimension']} | {v['input_size']} |")
    lines+=['','Für die 512px-Anpassung werden die letzten zwei Inverted-Residual-Blöcke, der letzte Projektionsblock und der lineare Kopf gelernt. Präfix und BatchNorm-Statistiken/-Parameter bleiben eingefroren. AdamW, drei Epochen, kein Test-Tuning; ein unveränderter Kandidat (Epoche 0) kann gewinnen. Dies ist partielles Fine-Tuning, kein vollständiges End-to-End-Training.','','| Epoche | Training-NLL | Modellwahl-NLL |','|---|---:|---:|']
    for v in sel['history']:lines.append(f"| {v['epoch']} | {v.get('training_nll','–')} | {v['selection_nll']:.5f} |")
    lines+=['','Das Protokoll wurde vor Training und Testauswertung versioniert. Nach einer reinen Laufzeitmessung wurde der zunächst geplante ResNet-512/ResNet50-Vergleich an die CPU-Umgebung angepasst: vollständiger Bestand mit MobileNet bei beiden Auflösungen und ResNet18 als größere Referenz. Keine Testwerte bestimmten diese Änderung. [Finales Protokoll](../../configs/original_512.json), Git-Historie `5416738`, `3753a42`, `99eefc0`.','','## Unsicherheit und Grenzen','','2.000 gemeinsame Wiederziehungen der 426 aus Dateinamen abgeleiteten Testgruppen, jeweils mit allen Bildern der gezogenen Gruppe. Die Intervalle berücksichtigen diese Gruppierung, aber keine unbekannten Identitätsverknüpfungen, Trainingsseed-Streuung oder Modellwahlunsicherheit. Sekundäre Vergleiche sind nicht multiplikativ korrigiert. Ein Seed und drei Anpassungsepochen belegen kein Optimum. Weitere Standorte, Geräte, Altersgruppen, Störungen und unabhängige Kohorten fehlen. Ein gutes internes Ergebnis ist kein Beleg klinischer Einsatzreife.','','## SwiftUI und Export','','Ein lokaler vollständiger PyTorch-Checkpoint und TorchScript-Export werden unter `data/original_xray/` gespeichert; die Einbindung des angepassten Encoders und des gefalteten Scalers wurde an Modellwahlbeispielen gegengeprüft. Der Core-ML-Export und sein tatsächlicher Prüfstatus stehen in [deployment.json](deployment.json). Ein [SwiftUI-Tensorprüfer](../../ios/ResearchPrototype/README.md) verwendet eine synthetische Referenzeingabe. Xcode-Kompilation, Apple-Laufzeit, Bildvorverarbeitung auf iOS, reale Latenz und Speicherbedarf auf Geräten bleiben eigenständige Prüfungen.','','Die Gewichte, Originalbilder, Feature-Caches und das lokale Core-ML-Paket werden nicht im Git-Repository verteilt. Modellhashes und kleine numerische Artefakte sichern die Zuordnung; für Weitergabe gelten die dokumentierten Quellen und [Lizenzgrenzen](../../docs/LICENSING.md).','','## Reproduktion','','```bash','python scripts/fetch_original_xray.py','python scripts/prepare_original_xray.py','python experiments/original_512.py','python scripts/verify_original_512.py','python scripts/plot_original_512.py','python scripts/export_original_coreml.py','python scripts/report_original_512.py','```','','Feature-Caches sind durch Manifest-/Code-/Protokollhashes gebunden; für geänderte Vorverarbeitung oder Experimente einen separaten Cache verwenden. Die Export-Abhängigkeit ist optional in `requirements-coreml.txt`; Training verwendet die vorhandene CPU-PyTorch-Umgebung.','','[Ergebnisse](results.csv) · [Zusammenfassung](summary.json) · [Vorhersagen](predictions.npz) · [Gruppenbootstrap](bootstrap.npz) · [Unabhängige Prüfung](verification.json).']
    if (out/'threshold_transfer/summary.json').exists():
        transfer=json.loads((out/'threshold_transfer/summary.json').read_text())
        lines+=['','## Nachanalyse: Schwellen übertragen sich schlecht','','Nach Sichtung der geringen Testspezifität wurde eine separate diagnostische Analyse festgelegt. Je Modell werden Schwellen ausschließlich auf Kalibrierungs-Normalbildern für mindestens 90 % bzw. 95 % empirische Spezifität bestimmt. In jeder der 2.000 Wiederziehungen werden Kalibrierungs- und Testgruppen unabhängig gezogen und die Schwellen neu angepasst. Bildgewichtete Kennzahlen mit Gruppierung der Unsicherheit; keine unabhängige Bestätigung und keine klinischen Garantien.','','| Modell / Kalibrierungsziel | Erreichte Kalibrierungs-Spezifität | Test-Spezifität [95 %] | Test-Sensitivität |','|---|---:|---:|---:|']
        for k,v in transfer['results'].items():
            ci=v['test_specificity_interval']['ci'];lines.append(f"| {k} | {v['calibration_specificity']:.1%} | {v['test_specificity']:.1%} [{ci[0]:.1%}; {ci[1]:.1%}] | {v['test_sensitivity']:.1%} |")
        lines+=['','Beim angepassten 512px-Modell fällt die Spezifität bereits an der unveränderten 0,5-Klassenschwelle von 98,4 % im Kalibrierungsbestand auf 54,5 % im Test. Die NLL steigt von 0,056 auf 0,621. Eine auf 95 % Kalibrierungs-Spezifität gesetzte Schwelle erreicht im Test nur 52,4 %. Dies belegt eine deutliche Übertragungslücke in diesem Datensatz; deren Ursache (Aufnahmebedingungen, Fallmischung, Artefakte oder andere Faktoren) ist damit nicht isoliert. Mehr Parameter oder weitere Epochen lösen diese Lücke nicht nachweislich.','','Die Modelle und der Core-ML-Export bleiben unverändert; die diagnostischen Schwellen werden nicht als neue App-Entscheidungsregeln übernommen. [Vorab festgelegter Nachanalyseplan](../../configs/original_512_threshold_transfer.json), [alle Teilmengen und Schwellen](threshold_transfer/summary.json), [12.000 unabhängig nachgerechnete Schwellenfits](threshold_transfer/verification.json).']
    if (out/'head_control/summary.json').exists():
        control=json.loads((out/'head_control/summary.json').read_text());v=control['fine_minus_head']['auroc'];risk=control['fine_minus_head']['risk_at_80']
        lines+=['','## Kontrolle: gleicher Optimierer, nur der Kopf lernt','',f"Ein zusätzlicher Kontrollarm erhält denselben initialen 512px-Kopf, AdamW, Lernrate, Gewichtszerfall, Batchgröße, drei Epochen und dieselben Bildreihenfolgen. Nur die Encoderanpassung entfällt. Gewählte Epoche: {control['selected_epoch']}. Nachtrainierter Encoder minus reine Kopfanpassung: **AUROC {v['point']:+.4f} [{v['ci'][0]:+.4f}; {v['ci'][1]:+.4f}]**, Risiko bei 80 % **{risk['point']*100:+.2f} pp [{risk['ci'][0]*100:+.2f}; {risk['ci'][1]*100:+.2f}]**.",'','Damit wird geprüft, ob eine Änderung allein durch das erneute Optimieren des Klassifikationskopfs erklärbar ist. Weiterhin bedingt auf ausgewählte Modelle, kein unabhängiger kausaler oder klinischer Nachweis. Vor Betrachtung der neuen Testergebnisse festgelegt (`fdb6ab6`). [Protokoll](../../configs/original_512_head_control.json), [Ergebnisse](head_control/summary.json), [Prüfung](head_control/verification.json).']
    if large is not None:
        v=large['contrast']['auroc'];m=large['metrics']
        lines+=['','## Zusätzlicher größerer Encoder: ResNet-50','',f"ResNet-50 umfasst mit neuem Kopf **{large['parameters']:,} Parameter**. Gleicher bereinigter Bestand und dieselbe 224px-Vorverarbeitung. Test-AUROC **{m['auroc']:.4f}**; ResNet50 minus ResNet18 **{v['point']:+.4f} [{v['ci'][0]:+.4f}; {v['ci'][1]:+.4f}]**. Sensitivität {m['sensitivity']:.1%}, Spezifität {m['specificity']:.1%}; sekundärer Architekturvergleich.",'','Diese Ergänzung wurde während der 512px-Merkmalsberechnung und vor Betrachtung der neuen Testergebnisse festgelegt (`3c2b740`). Sie verändert den primären Auflösungsvergleich nicht. Trainiert wurde ein neuer Kopf auf einem eingefrorenen ResNet-50; dies ist kein vollständiges Fine-Tuning des großen Encoders. [Protokoll](../../configs/original_512_large.json), [Ergebnisse](large_encoder/summary.json), [unabhängige Prüfung](large_encoder/verification.json).']
    if (out/'class_breakdown.json').exists():
        detail=json.loads((out/'class_breakdown.json').read_text())
        lines+=['','## Klassenbezogener Ausgangspunkt','','Sensitivität und Spezifität bei Logit-Schwelle 0, mit sekundären 95%-Gruppenbootstrap-Intervallen. Diese Schwelle ist nicht anhand klinischer Kosten optimiert.','','| Arm | Sensitivität | Spezifität | FN / positive Fälle | FP / negative Fälle |','|---|---:|---:|---:|---:|']
        for a,v in detail['results'].items():
            se=v['metrics']['sensitivity'];sp=v['metrics']['specificity'];c=v['confusion']
            lines.append(f"| {a} | {se['point']:.1%} [{se['ci'][0]:.1%}; {se['ci'][1]:.1%}] | {sp['point']:.1%} [{sp['ci'][0]:.1%}; {sp['ci'][1]:.1%}] | {c['fn']} / {c['fn']+c['tp']} | {c['fp']} / {c['fp']+c['tn']} |")
        lines+=['','Annahmequoten und verbleibende Fehler je Klasse sind vollständig in [class_breakdown.json](class_breakdown.json) gespeichert.']
    if (out/'runtime.json').exists():
        runtime=json.loads((out/'runtime.json').read_text())
        lines+=['','## Gemessener Rechenbedarf','','Lokale Linux-CPU, ein Torch-Thread, Batch 1, 5 Aufwärmläufe und 30 Messungen. Bereits normalisierter synthetischer Tensor; Laden, Bilddekodierung und Größenänderung fehlen. Das ist keine iPhone-Messung. Nicht gewählte Referenzarchitekturen verwenden für diese reine Laufzeitmessung zufällige Gewichte.','','| Architektur / Eingabe | Median ms | P90 ms |','|---|---:|---:|']
        for a,v in runtime['models'].items():lines.append(f"| {a} | {v['median_ms']:.1f} | {v['p90_ms']:.1f} |")
        lines+=['',f"Vollständiger lokaler 512px-Checkpoint: {runtime['checkpoint_bytes']/1e6:.2f} MB; TorchScript: {runtime['torchscript_bytes']/1e6:.2f} MB. [Messdaten](runtime.json)."]
    text='\n'.join(lines)+'\n'
    text=text.replace('Durchgeführt am 10. November 2026.','Ausgewertet am 11. November 2026; Trainingsläufe begonnen am 10. November.')
    text=text.replace('## Reproduktion','## Reproduktion\n\nDie vollständigen Trainingsbefehle in einer frischen Arbeitskopie ausführen, damit gespeicherte Studienausgaben erhalten bleiben.')
    text=text.replace('Die Gewichte, Originalbilder, Feature-Caches und das lokale Core-ML-Paket werden nicht im Git-Repository verteilt.','Vollständige Encoder-Checkpoints, Originalbilder, Feature-Caches und das lokale Core-ML-Paket werden nicht im Git-Repository verteilt. Kleine Klassifikationskopf-Parameter sind zur Nachrechnung versioniert.')
    text=text.replace('python experiments/original_512.py\n','python experiments/original_512.py\npython experiments/original_large_probe.py\npython experiments/original_head_control.py\npython experiments/original_threshold_transfer.py\n')
    text=text.replace('python scripts/verify_original_512.py\n','python scripts/verify_original_512.py\npython scripts/verify_original_large.py\npython scripts/verify_original_head_control.py\npython scripts/verify_original_threshold_transfer.py\npython scripts/characterize_original_512.py\n')
    text=text.replace('python scripts/report_original_512.py\n','python scripts/report_original_512.py\npython scripts/build_original_512_report.py\n')
    (out/'README.md').write_text(text)

if __name__=='__main__':main()
